-- VolleyLive 0021 (build 1.4.20): Ask VolleyLive (RAG phase 1) – the retrieval index.
-- ADDITIVE ONLY: one new table; nothing existing is touched. Re-run safe (IF NOT EXISTS).
-- Rows are generated by the server from src/core/helpFaq.ts + src/core/ask/rulesKnowledge.ts (our own summaries;
-- FIVB text is linked, never stored) and re-synced when that content changes (content_sha). Vectors are local
-- embeddings (src/core/ask embed(), 512 numbers) – no external embedding service.
-- ;;
CREATE TABLE IF NOT EXISTS ask_chunks (
  id            VARCHAR(120)  NOT NULL COMMENT 'faq:<id>:<lang> | rules:<id>:<lang>',
  kind          ENUM('faq','rules') NOT NULL,
  lang          CHAR(2)       NOT NULL,
  title         VARCHAR(300)  NOT NULL,
  body          TEXT          NOT NULL,
  url           VARCHAR(500)  NOT NULL,
  vec           MEDIUMTEXT    NOT NULL COMMENT 'JSON array of EMBED_DIM numbers',
  content_sha   CHAR(64)      NOT NULL,
  updated_at    DATETIME(3)   NOT NULL,
  PRIMARY KEY (id),
  KEY ix_ask_lang (lang)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
